# >>> STATIC
_static_stacks_deployment_step_artifacts_artifact_name() {
    cat <<-'ARGCEOF'
	plan-description	Plan details
	apply-description	Apply details (outputs + resource changes)
	plan-debug-log	Plan execution logs
	apply-debug-log	Apply execution logs
ARGCEOF
}
# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_bool() {
    echo true
    echo false
}

_choice_output_name() {
    local json
    json="$(terraform output -json 2>/dev/null)" || return 0
    [[ -n "$json" ]] || return 0
    printf '%s' "$json" | jq -b -r 'keys[]' 2>/dev/null
}

_choice_path() {
    _argc_util_comp_path
}

_choice_state_address() {
    terraform state list 2>/dev/null
}

_choice_workspace() {
    terraform workspace list 2>/dev/null | sed 's/^[* ]*//'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
